29	  unsigned char* buffer = malloc(length);
30	  if (fread(buffer, length, 1, f) != 1) {
31	    fprintf(stderr, "Failed to read input\n");
32	    exit(1);
33	  }
34	
35	  /* Assuming `buffer` contains `length` bytes of input data */
36	  struct cbor_load_result result;
37	  cbor_item_t* item = cbor_load(buffer, length, &result);
38	  free(buffer);
