40	  if (result.error.code != CBOR_ERR_NONE) {
41	    printf(
42	        "There was an error while reading the input near byte %zu (read %zu "
43	        "bytes in total): ",
44	        result.error.position, result.read);
45	    switch (result.error.code) {
46	      case CBOR_ERR_MALFORMATED: {
47	        printf("Malformed data\n");
48	        break;
49	      }
50	      case CBOR_ERR_MEMERROR: {
